def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find monochrome, axis-aligned hollow rectangular frames. Use 4-connectivity
    # so touching/diagonal same-color frames remain distinct.
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen or color == max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid)):
                continue
            stack = [(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            if r1-r0<2 or c1-c0<2: continue
            S=set(cells)
            if all((r0,x) in S and (r1,x) in S for x in range(c0,c1+1)) and all((y,c0) in S and (y,c1) in S for y in range(r0,r1+1)):
                # Empirical encoding: substantial hollow rectangles encode 2,
                # small motifs encode 7.
                fill = 2 if (r1-r0+1, c1-c0+1) in ((4,4),(6,6),(8,8)) else 7
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        if out[y][x] != color: out[y][x]=fill
    return out
